def count_incremovable_subarrays(nums):
    answer=0
    for left in range(len(nums)):
        for right in range(left,len(nums)):
            remaining=nums[:left]+nums[right+1:]
            if all(a<b for a,b in zip(remaining,remaining[1:])):answer+=1
    return answer

